package bits.ui;
import bits.model.Category; import bits.model.Component; import javax.swing.*; import java.awt.*; import java.util.List;
class ComponentDialog extends JDialog {
 private boolean savedFlag = false;
 JTextField name=new JTextField(22),value=new JTextField(22),quantity=new JTextField("0",22),location=new JTextField(22); JTextArea notes=new JTextArea(3,22); JComboBox<Category> category;
 ComponentDialog(JFrame owner,List<Category> categories,Component existing){super(owner,existing==null?"Add component":"Edit component",true);category=new JComboBox<>();category.addItem(new Category(0,"Uncategorised"));for(Category c:categories)category.addItem(c);JPanel p=new JPanel(new GridBagLayout());p.setBorder(BorderFactory.createEmptyBorder(14,18,14,18));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(5,5,5,5);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;addRow(p,g,"Component name",name);addRow(p,g,"Value / rating",value);g.gridx=0;g.gridy++;p.add(new JLabel("Category"),g);g.gridx=1;p.add(category,g);addRow(p,g,"Quantity",quantity);addRow(p,g,"Storage location",location);g.gridx=0;g.gridy++;p.add(new JLabel("Notes"),g);g.gridx=1;p.add(new JScrollPane(notes),g);JButton save=new JButton("Save");g.gridx=1;g.gridy++;p.add(save,g);add(p);if(existing!=null){name.setText(existing.getName());value.setText(existing.getValue());quantity.setText(String.valueOf(existing.getQuantity()));location.setText(existing.getLocation());notes.setText(existing.getNotes());for(int i=0;i<category.getItemCount();i++)if(category.getItemAt(i).getId()==existing.getCategoryId())category.setSelectedIndex(i);}save.addActionListener(e->{try{if(name.getText().trim().isEmpty())throw new IllegalArgumentException("Component name is required.");int q=Integer.parseInt(quantity.getText().trim());if(q<0)throw new IllegalArgumentException("Quantity cannot be negative.");savedFlag=true;dispose();}catch(Exception ex){JOptionPane.showMessageDialog(this,"Check the fields: "+ex.getMessage());}});pack();setLocationRelativeTo(owner);Theme.styleWindow(this);save.setBackground(Theme.ACCENT);save.setForeground(Color.WHITE);}
 private void addRow(JPanel p,GridBagConstraints g,String label,JComponent field){g.gridx=0;g.gridy++;p.add(new JLabel(label),g);g.gridx=1;p.add(field,g);}
 int categoryId(){return ((Category)category.getSelectedItem()).getId();}String componentName(){return name.getText().trim();}String componentValue(){return value.getText().trim();}int componentQuantity(){return Integer.parseInt(quantity.getText().trim());}String componentLocation(){return location.getText().trim();}String componentNotes(){return notes.getText().trim();}boolean saved(){return savedFlag;}
}
